  "design_rules": {
    "unit_storage_rule": "同维度所有属性统一按 measurement_dimension.base_unit_id 指定的单位存储，attribute_def 不再冗余存储单位字段",
    "unit_conversion": "unit_of_measure.to_base_factor 用于将任意单位换算到基准单位。例如 inch->mm 系数为 25.4",
    "unit_scope_config": "attribute_unit_scope_config 控制运营录入时可用单位（类目/品牌/系列维度），不涉及前端展示。前端展示单位由 country_display_unit 控制",
    "country_display_unit": "前端展示单位配置：country_display_unit 表通过 category_id 可空实现兜底逻辑。category_id 为空=国家x维度默认，不为空=类目级覆盖。查询时先查类目级（country+dimension+category），没有则查国家级默认（country+dimension+category=null）。本期 country_code 写死 US",
    "attribute_value_split": "spu_attribute_value 和 standard_sku_attribute 的属性值按类型分存：text_value（文本）、numeric_value（数值，按基准单位存储）、option_id（枚举选项）",
    "three_layer_model": "标品层（厂商定义不可改）-> 实物商品层（一物一码独立状态）-> 渠道层（多渠道分发独立控价）",
    "value_level_rule": "attribute_scope_config.value_level 控制属性值存储层级（SPU/SKU/ITEM）。约束：key 属性->必须 SPU，sale 属性->必须 SKU，non_key 属性->灵活（SPU/SKU/ITEM 均可）。value_level=ITEM 的属性值存储在 product_attribute_value 表",
    "size_system_rule": "标准尺码体系：一个体系可适用多个类目（通过 size_system_category 中间表）。换算关系存一条双向隐含（查询时 source 和 target 都匹配）",
    "brand_size_rule": "品牌尺码体系：与 brand 1:1（brand_id 唯一），适用类目通过 brand_size_system_category 中间表多选。品牌尺码值通过 brand_size_mapping 映射到标准尺码值",
    "size_priority_rule": "商品发布时尺码体系优先级：优先匹配品牌专属尺码体系，无品牌体系则使用 attribute_size_system_scope_config 配置的标准体系",
    "size_scope_config_rule": "attribute_size_system_scope_config 按作用域（类目/类目x品牌/类目x系列）差异化配置属性支持的尺码体系，与 attribute_scope_config 同模式",
    "input_type_rule": "attribute_def.input_type 控制属性的录入组件：input（文本框）、select（单选下拉）、multi_select（多选）、image_upload（图片上传）。image_upload 时 attribute_type 仍为 text（值存图片 URL），前端根据 input_type 渲染对应组件",
    "display_group_rule": "attribute_def.display_group 标识属性的前端展示分组：dimension（尺寸类，用于示意图标注区）、spec（常规规格，用于参数表）。与 attribute_scope_config.attribute_type（key/sale/non_key）正交，两个维度独立",
    "dimension_display_rule": "品类尺寸展示机制：dimension_diagram 表存储品类级 SVG 示意图模板（含 data-slot 槽位标记），slot_mapping(JSON) 定义槽位名与 attribute_def 的映射。前端加载模板后将 display_group=dimension 的属性实测值填入对应槽位渲染。无模板的品类退化为纯文字列表展示尺寸值。单位由前端根据类目适用单位和用户市场偏好统一处理，模板不涉及单位",
    "listing_title_rule": "listing.listing_title 渠道展示标题，VARCHAR(500)，可选。不同渠道可设不同标题。为空时前端兜底取 product.title，product.title 也为空时系统自动拼接 {关键属性值} {spu_name}",
    "listing_description_rule": "listing.listing_description 渠道展示描述，TEXT，可选。营销性描述文案。为空时前端兜底取 spu.description",
    "listing_currency_rule": "listing.currency_code 定价货币，创建时自动赋值：channel.market_id → market_currency(is_default=true) → currency_code 写入，运营不可手动选择。用于前端判断是否需要币种转换",
    "promotion_price_rule": "活动价（promotion_price）由促销模块外部计算输出，不存储在 listing 表中。前端调用促销模块接口获取当前 listing 的促销价",
    "product_status_rule": "product.product_status 实物商品生命周期状态，枚举：待核验/核验中/待销售/销售中/已售出/已停售/已失效（7态）。状态流转由业务操作驱动，详见 PRD 状态联动规则",
    "grade_rule": "product.grade 成色等级，枚举：NWT（近全新带标签）/Excellent（几乎全新）/Good（轻微使用痕迹）/Fair（明显使用痕迹）。从 product_inspection 提取冗余存储，便于列表筛选",
    "stock_mode_rule": "product.stock_mode 库存模式：现货（仓内实物）/ 预售（确认供货后再入仓），影响前端展示和履约时效",
    "channel_market_rule": "channel.market_id 跨模块 FK 指向 Market 模块的 market 表。一个 Market 下有多个渠道。channel 不再存佣金率（归支付结算模块）",
    "channel_sync_rule": "channel.sync_strategy 同步策略：manual（手动推送 listing 数据）/ auto（系统自动同步），控制商品数据向三方平台的推送方式"
  }
}
